import math, struct

MOD = (1<<61)-1

def hash_int_rust(i):
    m = MOD
    if i >= 0:
        h = i % m
    else:
        h = -((-i) % m)
    return -2 if h == -1 else h

# compare small and large ints
samples = [0,1,-1,2,-2,10**6,-10**6, 2**60, 2**61-2, 2**61-1, -(2**61-1), 2**62, -(2**62), 2**63-1, -(2**63), 10**18, -10**18, 10**30, -10**30]
