print("int mismatches", bad)

def frexp_rust(x):
    bits = struct.unpack('>Q', struct.pack('>d', x))[0]
    exp = (bits >> 52) & 0x7FF
    if exp == 0:
        m,e = frexp_rust(x * struct.unpack('>d', struct.pack('>Q', 0x4350000000000000))[0])
        return m, e-54
    mant = (bits & ~(0x7FF << 52)) | (1022 << 52)
    m = struct.unpack('>d', struct.pack('>Q', mant))[0]
    # sign is in mant bits already
    return m, exp - 1022

def hash_float_rust(v):
    if math.isnan(v):
        return 0
    if math.isinf(v):
        return 314159 if v > 0 else -314159
    if v == 0.0:
