import re

def split_args(s):
    args = []
    cur = []
    depth = 0
    i = 0
    while i < len(s):
        c = s[i]
        if c == '(' or c == '[' or c == '{':
            depth += 1
            cur.append(c)
        elif c == ')' or c == ']' or c == '}':
            depth -= 1
            cur.append(c)
        elif c == ',' and depth == 0:
            args.append(''.join(cur).strip())
            cur = []
        else:
            cur.append(c)
        i += 1
    if cur:
        args.append(''.join(cur).strip())
    return args

entries = []
i = 0
while True:
    m = re.search(r'\b(n!|m!|p!)\(', defs[i:])
    if not m:
        break
    kind = m.group(1)
    start = i + m.end()
    depth = 1
    j = start
    while j < len(defs) and depth:
        if defs[j] == '(':
            depth += 1
        elif defs[j] == ')':
            depth -= 1
        j += 1
    body = defs[start:j-1]
    args = split_args(body)
    entries.append((kind, args))
    i = j

print("parsed", len(entries))
# show a few of each
for k in ("n!", "m!", "p!"):
    print(k, sum(1 for e in entries if e[0]==k))

# normalize to (kind, name, owner_or_module, fn)
rows = []
bad = []
for kind, args in entries:
    if kind == "n!":
        if len(args) != 7:
            bad.append((kind, args))
            continue
        name, owner, mn, mx, params, kw, fn = args
        rows.append(("fn" if owner.strip()=="None" else "method", name.strip('"'), owner.strip(), fn.strip().replace("\n"," ")))
    elif kind == "m!":
        if len(args) != 7:
            bad.append((kind, args))
            continue
        mod, name, mn, mx, params, kw, fn = args
        rows.append(("mod", name.strip('"'), mod.strip().strip('"'), fn.strip().replace("\n"," ")))
    elif kind == "p!":
        if len(args) != 4:
            bad.append((kind, args))
            continue
        name, mn, mx, fn = args
        rows.append(("prelude", name.strip('"'), "_prelude", fn.strip().replace("\n"," ")))

print("rows", len(rows), "bad", len(bad))
if bad:
    for b in bad[:10]:
