import os, re, tokenize, io
from pathlib import Path

root = Path('/home/me/dev/mm-review/w4/conformance/own')
files = sorted(p for p in root.rglob('*.py'))
print('py files', len(files))

kw = {'raise', 'try', 'except'}

def keywords_in(path: Path):
    src = path.read_text(encoding='utf-8')
    found = set()
    counts = {k: 0 for k in kw}
    try:
        toks = tokenize.generate_tokens(io.StringIO(src).readline)
        for tok in toks:
            if tok.type == tokenize.NAME and tok.string in kw:
                found.add(tok.string)
                counts[tok.string] += 1
    except tokenize.TokenError as e:
        return {'error': str(e)}
    return {'found': sorted(found), 'counts': counts}

hits = []
errors = []
for p in files:
    r = keywords_in(p)
    if 'error' in r:
        errors.append((str(p), r['error']))
    elif r['found']:
        hits.append((str(p.relative_to(root)), r))

print('files with raise/try/except tokens:', len(hits))
print('tokenize errors:', len(errors))
for e in errors:
    print('ERR', e)
print('---')
for rel, r in hits:
    c = r['counts']
    print(f"{rel}: raise={c['raise']} try={c['try']} except={c['except']}")

