import math, struct, random
MOD = (1<<61)-1

def frexp(x):
    bits = struct.unpack('<Q', struct.pack('<d', x))[0]
    exp = (bits >> 52) & 0x7FF
    if exp == 0:
        m,e = frexp(x * struct.unpack('<d', struct.pack('<Q', 0x4350000000000000))[0])
        return m, e-54
    mbits = (bits & ~(0x7FF << 52)) | (1022 << 52)
    m = struct.unpack('<d', struct.pack('<Q', mbits))[0]
    return m, exp-1022

def hash_float(v):
    if math.isnan(v):
        return 0
    if math.isinf(v):
        return 314159 if v > 0 else -314159
    if v == 0.0:
        return 0
    m,e = frexp(v)
    sign = 1
    if m < 0:
        sign = -1
        m = -m
    x = 0
    while m != 0.0:
        x = ((x << 28) & MOD) | (x >> (61-28))
        m *= 268435456.0
        e -= 28
        y = int(m)  # trunc toward 0, m>=0
        m -= float(y)
        x += y
        if x >= MOD:
            x -= MOD
    if e >= 0:
        e = e % 61
    else:
        e = 61 - 1 - ((-1 - e) % 61)
    x = ((x << e) & MOD) | (x >> (61 - e))
    h = x * sign
    # signed 64
    if h >= 2**63:
        h -= 2**64
    if h < -2**63:
        h += 2**64
    if h == -1:
        h = -2
    return h

vals = [0.0, -0.0, 1.0, -1.0, 0.5, 2.0, 1.5, 10.0, math.inf, -math.inf, math.nan, float('-nan'),
        1e-320, -1e-320, 5e-324, -5e-324, 1e308, -1e308, 2**53, 2**53+2, 0.1, 0.3, math.pi,
        1.0000000000000002, -0.1, 123456789.0, 1e-10, 2**-1074, -2**-1074, 2**-1022, 2**-1021*(1+2**-52)]
# random
rnd = random.Random(0)
for _ in range(2000):
