r = await proc.run(["python3.14", "-c", r"""
import ast, pathlib, tokenize, io
root = pathlib.Path('conformance/own')
files = sorted(root.glob('*.py'))
print('total py', len(files))

def has_kw(src):
    # tokenize so comments and strings don't count
    kinds = set()
    try:
        toks = tokenize.generate_tokens(io.StringIO(src).readline)
        for tok in toks:
            if tok.type == tokenize.NAME and tok.string in ('raise', 'try', 'except'):
                kinds.add(tok.string)
    except tokenize.TokenError:
        return kinds, 'token-error'
    return kinds, None

kw_files = []
comment_only = []
for p in files:
    src = p.read_text()
    kinds, err = has_kw(src)
    if kinds:
        kw_files.append((p.name, sorted(kinds)))
    else:
        # raw word in comments/strings?
        import re
        if re.search(r'\b(raise|try|except)\b', src):
            comment_only.append(p.name)

print('syntax keyword files', len(kw_files))
print('comment/string only', len(comment_only), comment_only)

# also ast: Raise, Try, ExceptHandler
ast_files = []
for p in files:
    src = p.read_text()
    try:
        tree = ast.parse(src)
    except SyntaxError as e:
        print('syntax error', p, e)
        continue
    found = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Raise):
            found.add('raise')
        elif isinstance(n, ast.Try):
            found.add('try')
        elif isinstance(n, ast.ExceptHandler):
            found.add('except')
    if found:
        ast_files.append((p.name, sorted(found)))
print('ast files', len(ast_files))

# difference token vs ast
tokset = {n for n,_ in kw_files}
astset = {n for n,_ in ast_files}
print('token not ast', sorted(tokset-astset))
print('ast not token', sorted(astset-tokset))

only_try = [n for n,k in ast_files if k==['try']]
print('only try (no except/raise nodes?)', only_try)
# Try node always has handlers or finalbody
# classify
from collections import Counter
c = Counter()
for n,k in ast_files:
    c[tuple(k)] += 1
print('combos:')
for k,v in sorted(c.items(), key=lambda x: -x[1]):
    print(f'  {v:3} {k}')
"""])
